TASK
Create controllable promise delays with optional values, ranges, rejection, and cancellation.

PUBLIC CONTRACT
Module: await load('./index.js'); default export delay (CommonJS).
delay(milliseconds, {value?, signal?}?) creates a promise resolving after the delay with value. delay.reject(milliseconds, options?) rejects with the supplied value after the delay. delay.range(minimum, maximum, options?) resolves after a random integer number of milliseconds in the inclusive range, using the same value and signal options. Returned delay promises have .clear(), which cancels the timer and settles immediately according to the selected resolve/reject operation. An aborted signal rejects with an Error named AbortError.
delay.createWithTimers({setTimeout, clearTimeout}) creates an independent delay instance using the supplied timer functions. This instance provides the delay operations with the same API. Timers receive (callback, milliseconds), return a handle, and clearTimeout receives that handle.

SOURCE index.js
   1: 'use strict';
   2: 
   3: // From https://github.com/sindresorhus/random-int/blob/c37741b56f76b9160b0b63dae4e9c64875128146/index.js#L13-L15
   4: const randomInteger = (minimum, maximum) => Math.floor((Math.random() * (maximum - minimum + 1)) + minimum);
   5: 
   6: const createAbortError = () => {
   7: 	const error = new Error('Delay aborted');
   8: 	error.name = 'AbortError';
   9: 	return error;
  10: };
  11: 
  12: const createDelay = ({clearTimeout: defaultClear, setTimeout: set, willResolve}) => (ms, {value, signal} = {}) => {
  13: 	if (signal && signal.aborted) {
  14: 		return Promise.reject(createAbortError());
  15: 	}
  16: 
  17: 	let timeoutId;
  18: 	let settle;
  19: 	let rejectFn;
  20: 	const clear = defaultClear || clearTimeout;
  21: 
  22: 	const signalListener = () => {
  23: 		clear(timeoutId);
  24: 		rejectFn(createAbortError());
  25: 	};
  26: 
  27: 	const cleanup = () => {
  28: 		if (signal) {
  29: 			signal.removeEventListener('abort', signalListener);
  30: 		}
  31: 	};
  32: 
  33: 	const delayPromise = new Promise((resolve, reject) => {
  34: 		settle = () => {
  35: 			cleanup();
  36: 			if (willResolve) {
  37: 				resolve(value);
  38: 			} else {
  39: 				reject(value);
  40: 			}
  41: 		};
  42: 
  43: 		rejectFn = reject;
  44: 		timeoutId = (set || setTimeout)(settle, ms);
  45: 	});
  46: 
  47: 	if (signal) {
  48: 		signal.addEventListener('abort', signalListener, {once: true});
  49: 	}
  50: 
  51: 	delayPromise.clear = () => {
  52: 		clear(timeoutId);
  53: 		timeoutId = null;
  54: 		settle();
  55: 	};
  56: 
  57: 	return delayPromise;
  58: };
  59: 
  60: const createWithTimers = clearAndSet => {
  61: 	const delay = createDelay({...clearAndSet, willResolve: true});
  62: 	delay.reject = createDelay({...clearAndSet, willResolve: false});
  63: 	delay.range = (minimum, maximum, options) => delay(randomInteger(minimum, maximum), options);
  64: 	return delay;
  65: };
  66: 
  67: const delay = createWithTimers();
  68: delay.createWithTimers = createWithTimers;
  69: 
  70: module.exports = delay;
  71: // TODO: Remove this for the next major release
  72: module.exports.default = delay;

